const chunk_length_seconds = $('Set video object').first().json.video.image_length_seconds;
const chars_per_minute = 1000;
const chunk_character_length = Math.ceil(chars_per_minute * (chunk_length_seconds / 60));

function splitTextToChunks(text, characterLimit) {
  if (text.length <= characterLimit) {

    return [text];
  }
  const tmpChunks = [[]];
  for (const sentence of text.split('.')) {
    if (
      tmpChunks[tmpChunks.length - 1].join('').length >= characterLimit 
    ) {
      tmpChunks.push([]);
    }
    tmpChunks[tmpChunks.length - 1].push(sentence);
  }
  return tmpChunks.map(item => item.join('. ')).filter(Boolean);
}

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.chunk_character_length = chunk_character_length;
  item.json.chunks = [
    ...splitTextToChunks($('Set video object').first().json.video.intro, chunk_character_length),
    ...splitTextToChunks($('Set video object').first().json.video.story, chunk_character_length)
  ];
}

return $input.all();

