const chunks = []
// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  chunks.push(item.json)
}

chunks.sort((a, b) => {
  if (a.id > b.id) {
    return 1;
  } else if (b.id > a.id) {
    return -1;
  }
  return 0;
})

return [{
  json: {
    video_ids: chunks.map(item => item.generated_video_id).join(",")
  }
}]

